Object.assign(screens,{
d2reflect(){shell(`<div class="eyebrow danger">День 2 / контрольный вопрос</div><h2>Что изменится, если человек не врёт, а просто не может?</h2><p class="lead">Выберите ближайший ответ или сформулируйте свой.</p>${editableSingle({key:'trustReflection',presetKey:'x4',options:['Мне понадобится резервный исполнитель','Придётся проверить способность до основного решения','Нужно снизить зависимость от одного человека','Нужно разделить обещание на контрольные этапы','Цена решения станет выше','Решение придётся отложить'],value:state.trustReflection,label:'Ваш ответ'})}${err('reflectErr')}<div class="footer-nav">${back('d2cost')}<button class="btn" id="reflectNext">Получить результат дня</button></div>`)},
d2summary(){summary(2,'d3intro')},
d3intro(){dayIntro(3,'Где тут может быть пиздец','А — альтернативы / premortem','d3failures')},
d3failures(){shell(`<div class="eyebrow danger">День 3 / premortem</div><h2>Почему всё закончилось плохо?</h2><p class="lead">Сначала выберите типовые версии. Потом добавьте свои. Нужно минимум 15; выбранные пункты можно переписать.</p>${multiPicker({key:'failureModes',options:failureOptions[state.domain]||[],min:15,placeholder:'Добавьте ещё один независимый способ провала'})}${state.failureModes.length>=5?valentin(quotes.day3):''}${err('failureErr')}<div class="footer-nav">${back('d3intro')}<button class="btn" id="failureNext">Продолжить</button></div>`)},
d3uncomfortable(){shell(`<div class="eyebrow">День 3 / неприятная версия</div><h2>Какую причину вам хочется считать маловероятной?</h2>${editableSingle({key:'uncomfortableFailure',presetKey:'x5',options:(failureOptions[state.domain]||[]).slice(0,6),value:state.uncomfortableFailure,label:'Выбранная неприятная версия'})}<label for="uncomfortableWhy">Почему хочется её обесценить?</label><textarea id="uncomfortableWhy">${esc(state.uncomfortableWhy)}</textarea>${err('uncomfortableErr')}<div class="footer-nav">${back('d3failures')}<button class="btn" id="uncomfortableNext">Получить результат дня</button></div>`)},
d3summary(){summary(3,'d4intro')},
d4intro(){dayIntro(4,'Слабые сигналы','С — сигналы','d4signals')},
d4signals(){shell(`<div class="eyebrow danger">День 4 / ранние сигналы</div><h2>Что покажет, что ситуация идёт не туда?</h2><p class="lead">Выберите минимум пять ранних признаков и при необходимости добавьте свои.</p>${multiPicker({key:'signals',options:signalOptions[state.domain]||[],min:5,placeholder:'Добавьте ранний сигнал'})}${err('signalsErr')}<div class="footer-nav">${back('d4intro')}<button class="btn" id="signalsNext">Продолжить</button></div>`)},
d4rationalize(){shell(`<div class="eyebrow">День 4 / рационализация</div><h2>Какой сигнал вы скорее всего попытаетесь объяснить?</h2>${editableSingle({key:'rationalizedSignal',presetKey:'x6',options:(signalOptions[state.domain]||[]).slice(0,6),value:state.rationalizedSignal,label:'Сигнал'})}<label for="rationalization">Как вы его обычно обезвредите словами?</label><textarea id="rationalization">${esc(state.rationalization)}</textarea>${valentin(quotes.day4)}${err('rationalErr')}<div class="footer-nav">${back('d4signals')}<button class="btn" id="rationalNext">Продолжить</button></div>`)},
d4trigger(){shell(`<div class="eyebrow danger">День 4 / точка перепроверки</div><h2>После какого события вы обязаны перепроверить гипотезу?</h2>${editableSingle({key:'recheckTrigger',presetKey:'recheckPreset',options:triggerOptions,value:state.recheckTrigger,label:'Точка перепроверки'})}${err('triggerErr')}<div class="footer-nav">${back('d4rationalize')}<button class="btn" id="triggerNext">Получить результат дня</button></div>`)},
d4summary(){summary(4,'d5intro')},
d5intro(){dayIntro(5,'Красные флаги для бедных. У нас — система','Н — необратимость','d5states')},
d5states(){shell(`<div class="eyebrow">День 5 / три состояния</div><h2>Где зелёное, жёлтое и красное?</h2><div class="option-title">Зелёное</div>${editableSingle({key:'greenState',presetKey:'x7',options:greenOptions,value:state.greenState,label:'Всё допустимо, когда...'})}<div class="option-title">Жёлтое</div>${editableSingle({key:'yellowState',presetKey:'x8',options:yellowOptions,value:state.yellowState,label:'Нужно перепроверить, когда...'})}<div class="option-title">Красное</div>${editableSingle({key:'redLine',presetKey:'x9',options:redOptions,value:state.redLine,label:'Решение меняется или прекращается, когда...'})}${err('statesErr')}<div class="footer-nav">${back('d5intro')}<button class="btn" id="statesNext">Продолжить</button></div>`)},
d5irreversible(){const opts=['деньги','время','договор','репутацию','отношения','обязательства','здоровье / безопасность'];shell(`<div class="eyebrow">День 5 / необратимость</div><h2>Что будет трудно вернуть?</h2><div class="choice-grid">${opts.map(x=>`<button class="choice ${state.irreversible.includes(x)?'selected':''}" data-irrev="${x}">${x}</button>`).join('')}</div>${err('irrevErr')}<div class="footer-nav">${back('d5states')}<button class="btn" id="irrevNext">Продолжить</button></div>`)},
d5sunk(){const scenario=state.domain==='people'?'Вы уже сильно вложились в отношения и договорённости. Сработал заранее записанный красный сигнал.':state.domain==='home'?'Вы уже потратили значимые деньги и время. Сработал заранее записанный красный сигнал.':'Вы уже вложили значимую сумму и время. Сработал заранее записанный красный сигнал.';shell(`<div class="eyebrow danger">День 5 / sunk cost</div><h2>Красная линия уже сработала</h2><div class="case">${esc(scenario)}</div><div class="choice-grid" style="grid-template-columns:1fr 1fr"><button class="choice ${state.sunkChoice==='continue'?'selected':''}" data-sunk="continue">Продолжить</button><button class="choice ${state.sunkChoice==='stop'?'selected':''}" data-sunk="stop">Остановиться</button></div>${state.sunkChoice==='continue'?valentin('Именно поэтому красную линию полезно записывать до того, как появятся причины её передвинуть.'):''}${err('sunkErr')}<div class="footer-nav">${back('d5irreversible')}<button class="btn" id="sunkNext">Продолжить</button></div>`)},
d5redline(){shell(`<div class="eyebrow danger">День 5 / финальная красная линия</div><h2>Какое наблюдаемое условие действительно остановит решение?</h2>${editableSingle({key:'redLine',presetKey:'x10',options:redOptions,value:state.redLine,label:'Итоговая красная линия'})}${err('redlineErr')}<div class="footer-nav">${back('d5sunk')}<button class="btn" id="redlineNext">Получить результат дня</button></div>`)},
d5summary(){summary(5,'d6intro')},
d6intro(){dayIntro(6,'Не влюбляйся в собственную версию','проверка гипотезы','d6pros')},
d6pros(){shell(`<div class="eyebrow">День 6 / защита</div><h2>Почему ваша идея хорошая?</h2>${editableSingle({key:'proArguments',presetKey:'x11',options:prosOptions,value:state.proArguments,label:'Главный аргумент за'})}${err('prosErr')}<div class="footer-nav">${back('d6intro')}<button class="btn" id="prosNext">Продолжить</button></div>`)},
d6counter(){shell(`<div class="eyebrow danger">День 6 / прокурор</div><h2>Почему человек, который знает больше вас, мог бы считать её плохой?</h2>${editableSingle({key:'counterArguments',presetKey:'x12',options:counterOptions,value:state.counterArguments,label:'Главный аргумент против'})}${err('counterErr')}<div class="footer-nav">${back('d6pros')}<button class="btn" id="counterNext">Продолжить</button></div>`)},
});
